CREATE TABLE maintenance_private.variant_reset_20261110 AS SELECT * FROM public.product_variants WITH NO DATA;
REVOKE ALL ON maintenance_private.variant_reset_20261110 FROM PUBLIC,anon,authenticated;
DO $$ DECLARE targets uuid[] := ARRAY['02023c38-652c-4c26-acba-a1e115efdaaf'::uuid,'055a37a8-6861-4348-9a9b-9804b054163e'::uuid,'076faa32-12f8-4b68-bfa6-cb4611896957'::uuid,'08665793-4719-4278-90a3-39a16b42862e'::uuid,'11c77184-99b9-474e-b025-8400127a876c'::uuid,'13cfa421-05aa-44f7-9a53-d52eae21dd3f'::uuid,'19014307-374d-4bfb-bf6a-75d3ae191d4c'::uuid,'1a1e4cf2-da01-4361-8aa6-623028dbb926'::uuid,'1b226c4c-91d0-45ff-b65d-804ca485ffab'::uuid,'1b369d1f-b5b7-456a-978a-36e391f14433'::uuid,'1b5d85bc-e498-4506-aeb9-a320b901c795'::uuid,'1b9b9b4b-483b-4957-960d-3990cf8554cb'::uuid,'22c880f8-91dc-4919-a76e-fbc4b9a615c6'::uuid,'23e0b487-1b33-488c-bdf2-d07ed583d5e6'::uuid,'27d05435-441d-4916-8e4b-e7ee3924dfb5'::uuid,'28ca3cab-827d-45f9-a8c9-efaa6a1f5232'::uuid,'2b376493-0cb1-4267-b450-606cc73c955c'::uuid,'2ebd6ba9-2643-47fd-b232-389e4432dad9'::uuid,'2fe12c9e-0e1c-4d8f-aa89-0fd697549b62'::uuid,'3c253134-1b93-4ed0-adfe-7d44e3ebb166'::uuid,'40962b9e-c22f-4abd-9450-d5b6a2543694'::uuid,'41624085-4d55-41a6-b290-3d0658f80ffe'::uuid,'4b080c74-bff8-4906-ab5a-15fee18cf6c8'::uuid,'4d234d8a-2668-4c78-8f9f-3f659dc3289f'::uuid,'51fde7b5-02dd-40c3-9721-7018e9c25220'::uuid,'5a053ff0-dc09-45bd-968c-c7a27e6d956e'::uuid,'5a16c61b-f024-4ea5-9f56-3f77625e8038'::uuid,'60ff9015-6ba5-4ec4-903b-f3ae9a9bf035'::uuid,'61a0a56d-64dc-4f47-9a6e-a46960a612ac'::uuid,'69d1cf42-7084-4fee-a582-d98c2e5db4b8'::uuid,'6ea37e79-dda6-4afe-8f8a-70ab06bd8a92'::uuid,'7019fc51-2d49-44af-acdc-31736f2a5334'::uuid,'707423c9-f14b-443e-938b-aab6ee93bcd3'::uuid,'7347c7b2-c42a-49fb-bc80-f08c029b7472'::uuid,'7542cb83-553c-4b03-ae73-cc95c07479c4'::uuid,'75e01ae8-ed81-4ad6-a9e8-99cdec92be40'::uuid,'771cb4bc-176d-4663-ab74-64014ffda7f6'::uuid,'7d0cafb2-c18b-4fca-98ae-e75c42e75ad6'::uuid,'7efb097a-34b4-4e89-b06e-bfeea76a0be3'::uuid,'80d24817-b4d6-4c63-bd74-f95187bfe08f'::uuid,'851d4c0e-09d9-4194-9c89-661fbda07636'::uuid,'8c17a231-7942-4d75-a5d0-64681c43772b'::uuid,'8d4c57df-9016-4aaa-b597-0feaab0d13a5'::uuid,'93e0e047-8e12-4113-b547-73