 IF EXISTS(SELECT 1 FROM public.product_variants WHERE id=ANY(targets) AND coalesce(stock_quantity,0)<>0) THEN RAISE EXCEPTION 'Stock has changed'; END IF;
 INSERT INTO maintenance_private.variant_reset_20261110 SELECT * FROM public.product_variants WHERE id=ANY(targets);
 DELETE FROM public.product_variants WHERE id=ANY(targets);
